export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error('Unknown tool: ' + name);
  }
  const a = args || {};
  // validate query
  if (typeof a.query !== 'string') {
    throw new Error('query must be a string');
  }
  // validate no extra properties
  const allowed = new Set(['query','offset','limit']);
  for (const k of Object.keys(a)) {
    if (!allowed.has(k)) throw new Error('Unknown argument: ' + k);
  }
  // offset
  let offset = a.offset ?? 0;
  if (!Number.isInteger(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }
  // limit
  let limit = a.limit ?? 2;
  if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }

  const q = a.query.toLowerCase();
  const matches = items.filter(it => it.name.toLowerCase().includes(q));
  const page = matches.slice(offset, offset + limit);
  const nextOffset = (offset + limit < matches.length) ? offset + limit : null;
  const result = { items: page };
  if (nextOffset !== null) result.next_offset = nextOffset;
  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
